/// clean-kernel expr/meta.rs mix_hash — VERBATIM.
fn native_mix_hash(h: u64, k: u64) -> u64 {
    const M: u64 = 0xc6a4_a793_5bd1_e995;
    const R: u32 = 47;
    let mut k = k.wrapping_mul(M);
    k ^= k >> R;
    k ^= M;
    let h = h ^ k;
    h.wrapping_mul(M)
}

/// clean-kernel murmur_hash_64a in the PRODUCTION block form (as-chunks ≡
/// chunks_exact(8) + remainder) — the modules carry the index-loop
/// transcription, so agreement proves [T-murmur-idx] on every tested name.
fn native_murmur_hash_64a(data: &[u8], seed: u64) -> u64 {
    const M: u64 = 0xc6a4_a793_5bd1_e995;
    const R: u32 = 47;
    let len = data.len();
    let mut h: u64 = seed ^ (len as u64).wrapping_mul(M);
    let mut chunks = data.chunks_exact(8);
    for block in &mut chunks {
        let mut k = u64::from_le_bytes(block.try_into().expect("8-byte chunk"));
        k = k.wrapping_mul(M);
        k ^= k >> (R & 63);
        k = k.wrapping_mul(M);
        h ^= k;
        h = h.wrapping_mul(M);
    }
    let tail = chunks.remainder();
    for (i, &b) in tail.iter().enumerate() {
        h ^= (b as u64) << (i.wrapping_mul(8) & 63);
    }
    if !tail.is_empty() {
        h = h.wrapping_mul(M);
    }
    h ^= h >> (R & 63);
    h = h.wrapping_mul(M);
    h ^= h >> (R & 63);
    h
}

/// A decoded Name component, leaf-to-root.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Comp {
    Str(Vec<u8>),
    Num(u64),
}

// GOLDEN constants from the REAL clean-kernel binary (pinned in R4-R6; see
// e2e_universe_realnames.rs module docs for the pin recipe).
const GOLDEN_U: u64 = 0xae572a66f1f7b2e8;
const GOLDEN_V: u64 = 0x486e7075aebc6ca6;
const GOLDEN_NAT: u64 = 0x9ecc0d3a68dfdd9b;
const GOLDEN_AX_DUP: u64 = 0xfdb31ca9d0ac3c36;
const GOLDEN_THM42: u64 = 0xdcaef40c027c85c5;
const GOLDEN_ANON: u64 = 1723;

// ── the JIT-side raw Name decode (offsets identical to rounds 4-8) ──────────

/// Walk a JIT-built Name at `ptr`: returns (leaf-to-root comps, root hash,
/// per-node hashes leaf-to-root). Panics on an unknown tag (fail-loud decode).
unsafe fn decode_jit_name(ptr: *const u8) -> (Vec<Comp>, u64, Vec<u64>) {
    unsafe {
        let mut comps = Vec::new();
        let mut node_hashes = Vec::new();
        let read_u64 = |p: *const u8| -> u64 { (p as *const u64).read_unaligned() };
        let read_ptr = |p: *const u8| -> *const u8 { (p as *const *const u8).read_unaligned() };
        let root_hash = read_u64(ptr.add(32));
        let mut cur = ptr;
        loop {
            let tag = read_u64(cur);
            node_hashes.push(read_u64(cur.add(32)));
            match tag {
                0 => break,
                1 => {
                    let parent_inner = read_ptr(cur.add(8));
                    let s_inner = read_ptr(cur.add(16));
                    let s_len = read_u64(cur.add(24)) as usize;
                    let bytes = std::slice::from_raw_parts(s_inner.add(16), s_len).to_vec();
                    comps.push(Comp::Str(bytes));
                    cur = parent_inner.add(16);
                }
                2 => {
                    let n = read_u64(cur.add(8));
                    let parent_inner = read_ptr(cur.add(16));
                    comps.push(Comp::Num(n));
                    cur = parent_inner.add(16);
                }
                t => panic!("decode_jit_name: unknown NameInner tag {t} (layout drift?)"),
            }
        }
        (comps, root_hash, node_hashes)
    }
}

/// Recompute the production hash chain from decoded comps (leaf-to-root):
/// per-node hashes leaf-to-root INCLUDING the final Anon node (1723).
fn recompute_hash_chain(comps: &[Comp]) -> Vec<u64> {
    let mut fwd = vec![1723u64];
    for c in comps.iter().rev() {
        let prev = *fwd.last().unwrap();
        let h = match c {
            Comp::Str(b) => native_mix_hash(prev, native_murmur_hash_64a(b, 11)),
            Comp::Num(n) => native_mix_hash(prev, *n),
        };
        fwd.push(h);
    }
    fwd.reverse();
    fwd
}

/// SAFE walk of a HOST-built (mirror) Name: (leaf-to-root comps, root hash).
fn native_name_comps(n: &rn::Name) -> (Vec<Comp>, u64) {
    let mut comps = Vec::new();
    let mut cur = n;
    loop {
        match &cur.inner {
            rn::NameInner::Anon => break,
            rn::NameInner::Str(p, s) => {
                comps.push(Comp::Str(s.as_bytes().to_vec()));
                cur = &**p;
            }
            rn::NameInner::Num(p, v) => {
                comps.push(Comp::Num(*v));
                cur = &**p;
            }
        }
    }
    (comps, n.cached_hash)
}

// ════════════════════════════════════════════════════════════════════════════
// The asymmetric deep comparators (R6/R8 pattern): native side walked SAFELY
// via mirror types, JIT side Names decoded RAW with the per-node hash chain
// REVALIDATED on every comparison. Meta words compared bit-exact per node.
// ════════════════════════════════════════════════════════════════════════════

fn name_eq_nj(native: &rn::Name, jit: &rn::Name) -> bool {
    let (ncomps, nhash) = native_name_comps(native);
    let (jcomps, jhash, jchain) = unsafe { decode_jit_name(jit as *const rn::Name as *const u8) };
    let expect_chain = recompute_hash_chain(&jcomps);
    assert_eq!(
        jchain, expect_chain,
        "JIT Name per-node hash chain != production recompute (layout drift or hash bug?)"
    );
    ncomps == jcomps && nhash == jhash
}

fn level_eq_nj(native: &rn::Level, jit: &rn::Level) -> bool {
    match (native, jit) {
        (rn::Level::Zero, rn::Level::Zero) => true,
        (rn::Level::Succ(a), rn::Level::Succ(b)) => level_eq_nj(a, b),
        (rn::Level::Max(a1, b1), rn::Level::Max(a2, b2)) => {
            level_eq_nj(a1, a2) && level_eq_nj(b1, b2)
        }
        (rn::Level::IMax(a1, b1), rn::Level::IMax(a2, b2)) => {
            level_eq_nj(a1, a2) && level_eq_nj(b1, b2)
        }
        (rn::Level::Param(a), rn::Level::Param(b)) => name_eq_nj(a, b),
        _ => false,
    }
}

fn levels_eq_nj(native: &[rn::Level], jit: &[rn::Level]) -> bool {
    if native.len() != jit.len() {
        return false;
    }
    native
        .iter()
        .zip(jit.iter())
        .all(|(a, b)| level_eq_nj(a, b))
}

/// Deep native==JIT comparison: meta word BIT-IDENTICAL at every node, then
/// structural with production-name comparison at every Name site. FVar nodes
/// compare by id — the context-discipline observable.
fn deep_eq_nj(native: &rn::Expr, jit: &rn::Expr) -> bool {
    if native.meta.raw() != jit.meta.raw() {
        return false;
    }
    match (&native.kind, &jit.kind) {
        (rn::ExprKind::BVar(x), rn::ExprKind::BVar(y)) => x == y,
        (rn::ExprKind::FVar(x), rn::ExprKind::FVar(y)) => x == y,
        (rn::ExprKind::Lit(x), rn::ExprKind::Lit(y)) => x == y,
        (rn::ExprKind::Sort(x), rn::ExprKind::Sort(y)) => level_eq_nj(x, y),
        (rn::ExprKind::Const(n1, l1), rn::ExprKind::Const(n2, l2)) => {
            name_eq_nj(n1, n2) && levels_eq_nj(l1, l2)
        }
        (rn::ExprKind::App(f1, a1), rn::ExprKind::App(f2, a2)) => {
            deep_eq_nj(f1, f2) && deep_eq_nj(a1, a2)
        }
        (rn::ExprKind::Lam(b1, t1, y1), rn::ExprKind::Lam(b2, t2, y2)) => {
            b1 == b2 && deep_eq_nj(t1, t2) && deep_eq_nj(y1, y2)
        }
        (rn::ExprKind::Pi(b1, t1, y1), rn::ExprKind::Pi(b2, t2, y2)) => {
            b1 == b2 && deep_eq_nj(t1, t2) && deep_eq_nj(y1, y2)
        }
        (rn::ExprKind::Let(n1, t1, v1, y1, d1), rn::ExprKind::Let(n2, t2, v2, y2, d2)) => {
            name_eq_nj(n1, n2)
                && deep_eq_nj(t1, t2)
                && deep_eq_nj(v1, v2)
                && deep_eq_nj(y1, y2)
                && d1 == d2
        }
        (rn::ExprKind::Proj(n1, i1, e1), rn::ExprKind::Proj(n2, i2, e2)) => {
            name_eq_nj(n1, n2) && i1 == i2 && deep_eq_nj(e1, e2)
        }
        (rn::ExprKind::MData(m1, e1), rn::ExprKind::MData(m2, e2)) => {
            m1 == m2 && deep_eq_nj(e1, e2)
        }
        _ => false,
    }
}

fn type_error_disc(e: &rn::TypeError) -> u8 {
    match e {
        rn::TypeError::UnboundVariable(_) => 0,
        rn::TypeError::UnknownFVar(_) => 1,
        rn::TypeError::UnknownConst(_) => 2,
        rn::TypeError::TypeMismatch { .. } => 3,
        rn::TypeError::NotAPi { .. } => 4,
        rn::TypeError::ExpectedSort { .. } => 5,
        rn::TypeError::SortDepthExceeded { .. } => 6,
        rn::TypeError::Unsupported => 7,
    }
}

/// Payload-deep agreement between a native TypeError and a JIT TypeError.
fn type_error_agrees_nj(n: &rn::TypeError, j: &rn::TypeError) -> bool {
    if type_error_disc(n) != type_error_disc(j) {
        return false;
    }
    match (n, j) {
        (rn::TypeError::UnboundVariable(a), rn::TypeError::UnboundVariable(b)) => a == b,
        (rn::TypeError::UnknownFVar(a), rn::TypeError::UnknownFVar(b)) => a == b,
        (rn::TypeError::UnknownConst(a), rn::TypeError::UnknownConst(b)) => name_eq_nj(a, b),
        (
            rn::TypeError::TypeMismatch {
                expected: e1,
                inferred: i1,
            },
            rn::TypeError::TypeMismatch {
                expected: e2,
                inferred: i2,
            },
        ) => deep_eq_nj(e1, e2) && deep_eq_nj(i1, i2),
        (rn::TypeError::NotAPi { ty: t1 }, rn::TypeError::NotAPi { ty: t2 }) => deep_eq_nj(t1, t2),
        (rn::TypeError::ExpectedSort { ty: t1 }, rn::TypeError::ExpectedSort { ty: t2 }) => {
            deep_eq_nj(t1, t2)
        }
        (
            rn::TypeError::SortDepthExceeded { depth: a },
            rn::TypeError::SortDepthExceeded { depth: b },
        ) => a == b,
        _ => true,
    }
}

fn env_error_disc(e: &rn::EnvError) -> u8 {
    match e {
        rn::EnvError::TypeCheckFailed { .. } => 0,
        rn::EnvError::DuplicateLevelParam { .. } => 1,
        rn::EnvError::TheoremTypeNotProp { .. } => 2,
        rn::EnvError::ContainsFreeVar { .. } => 3,
        rn::EnvError::ContainsMetavar { .. } => 4,
        rn::EnvError::UndefinedLevelParam { .. } => 5,
    }
}

/// Payload-deep agreement between the native gate error and the JIT gate
/// error (the R6/R8 comparator).
fn env_error_agrees_nj(n: &rn::EnvError, j: &rn::EnvError) -> bool {
    if env_error_disc(n) != env_error_disc(j) {
        return false;
    }
    match (n, j) {
        (
            rn::EnvError::TypeCheckFailed {
                name: n1,
                source: s1,
            },
            rn::EnvError::TypeCheckFailed {
                name: n2,
                source: s2,
            },
        ) => name_eq_nj(n1, n2) && type_error_agrees_nj(s1, s2),
        (
            rn::EnvError::DuplicateLevelParam {
                name: n1,
                param: p1,
            },
            rn::EnvError::DuplicateLevelParam {
                name: n2,
                param: p2,
            },
        ) => name_eq_nj(n1, n2) && name_eq_nj(p1, p2),
        (
            rn::EnvError::TheoremTypeNotProp { name: n1, sort: s1 },
            rn::EnvError::TheoremTypeNotProp { name: n2, sort: s2 },
        ) => name_eq_nj(n1, n2) && level_eq_nj(s1, s2),
        (
            rn::EnvError::ContainsFreeVar { name: n1 },
            rn::EnvError::ContainsFreeVar { name: n2 },
        ) => name_eq_nj(n1, n2),
        (
            rn::EnvError::ContainsMetavar { name: n1 },
            rn::EnvError::ContainsMetavar { name: n2 },
        ) => name_eq_nj(n1, n2),
        (
            rn::EnvError::UndefinedLevelParam {
                name: n1,
                param: p1,
            },
            rn::EnvError::UndefinedLevelParam {
                name: n2,
                param: p2,
            },
        ) => name_eq_nj(n1, n2) && name_eq_nj(p1, p2),
        _ => false,
    }
}

// ── drivers ──────────────────────────────────────────────────────────────────

type BdGateFn = extern "C" fn(*mut Result<(), rn::EnvError>, *mut rn::Expr, u64);
type BdProbeFn = extern "C" fn(*mut Result<rn::Expr, rn::TypeError>, *mut rn::ProbeIds, u64);

fn jit_gate(f: BdGateFn, case: u64) -> (Result<(), rn::EnvError>, rn::Expr) {
    let mut res_slot = std::mem::MaybeUninit::<Result<(), rn::EnvError>>::uninit();
    let mut ty_slot = std::mem::MaybeUninit::<rn::Expr>::uninit();
    unsafe {
        f(res_slot.as_mut_ptr(), ty_slot.as_mut_ptr(), case);
        (res_slot.assume_init(), ty_slot.assume_init())
    }
}

/// The native BINDING-AWARE gate oracle — the mirror root, host-compiled.
fn native_gate_aware(case: u64) -> (Result<(), rn::EnvError>, rn::Expr) {
    let mut res_slot = std::mem::MaybeUninit::<Result<(), rn::EnvError>>::uninit();
    let mut ty_slot = std::mem::MaybeUninit::<rn::Expr>::uninit();
    unsafe {
        rn::bnd_gate_root(res_slot.as_mut_ptr(), ty_slot.as_mut_ptr(), case);
        (res_slot.assume_init(), ty_slot.assume_init())
    }
}

/// The native BINDING-BLIND control oracle — the mirror root, host-compiled.
fn native_gate_blind(case: u64) -> (Result<(), rn::EnvError>, rn::Expr) {
    let mut res_slot = std::mem::MaybeUninit::<Result<(), rn::EnvError>>::uninit();
    let mut ty_slot = std::mem::MaybeUninit::<rn::Expr>::uninit();
    unsafe {
        rn::bnd_blind_root(res_slot.as_mut_ptr(), ty_slot.as_mut_ptr(), case);
        (res_slot.assume_init(), ty_slot.assume_init())
    }
}

fn jit_probe(f: BdProbeFn, idx: u64) -> (Result<rn::Expr, rn::TypeError>, rn::ProbeIds) {
    let mut res_slot = std::mem::MaybeUninit::<Result<rn::Expr, rn::TypeError>>::uninit();
    let mut ids_slot = std::mem::MaybeUninit::<rn::ProbeIds>::uninit();
    unsafe {
        f(res_slot.as_mut_ptr(), ids_slot.as_mut_ptr(), idx);
        (res_slot.assume_init(), ids_slot.assume_init())
    }
}

/// The native probe oracle — the mirror root, host-compiled.
fn native_probe(idx: u64) -> (Result<rn::Expr, rn::TypeError>, rn::ProbeIds) {
    let mut res_slot = std::mem::MaybeUninit::<Result<rn::Expr, rn::TypeError>>::uninit();
    let mut ids_slot = std::mem::MaybeUninit::<rn::ProbeIds>::uninit();
    unsafe {
        rn::bnd_probe_root(res_slot.as_mut_ptr(), ids_slot.as_mut_ptr(), idx);
        (res_slot.assume_init(), ids_slot.assume_init())
    }
}

// Hand-built-name helper for pinned expectations (mirror machinery — the same
// fold production from_string performs).
fn hn1(s: &str) -> rn::Name {
    rn::fold_step(rn::name_anon(), s)
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 1 — module sanity: all three fixtures parse + validate 0; the R10
// surface is genuinely IN-MODULE and WIRED (call-graph edges in the emitted
// IR): def_eq_inner → is_def_eq_binding at the production call position;
// binding → the #3230 pre-check (expr_syntactic_eq), the fast-path gate
// (Expr__has_loose_bvars), ctx_push/open_bvar (the SHARED-id opening), the
// recursive def_eq, and the batch restore (LocalContext__truncate_to). The
// BLIND control module is the R9-landed configuration: raw congruence — the
// aware def_eq/binding chain STRUCTURALLY ABSENT — while its whnf still
// consults the context (zeta) and its proof-irrel chain is intact
// (self-contained _blind copies). The probe module carries BOTH chains plus
// the distinct-FVar control.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn bd_module_sanity_and_inmodule_surface() {
    let shared_syms = [
        "LocalContext__new",
        "LocalContext__push",
        "LocalContext__push_let",
        "LocalContext__pop",
        "LocalContext__get",
        "LocalContext__freshness_guard",
        "Expr__abstract_fvar",
        "Expr__subst_fvar",
        "Expr__instantiate",
        "name_anon",
        "name_str_part",
        "name_num_part",
        "murmur_hash_64a_idx",
        "mix_hash",
        "name_eq",
        "hash_name",
        "hash_levels",
        "ExprKind__compute_meta",
    ];
    for (text, what) in [
        (BD_GATE_TRUST_IR, "bnd_gate_root closure"),
        (BD_BLIND_TRUST_IR, "bnd_blind_root closure"),
        (BD_PROBE_TRUST_IR, "bnd_probe_root closure"),
    ] {
        let module = parse_and_validate(text, what);
        let bodied = |sym: &str| {
            module
                .functions
                .iter()
                .find(|f| f.name == sym)
                .map(|f| !f.blocks.is_empty())
                .unwrap_or(false)
        };
        for sym in shared_syms {
            assert!(
                bodied(sym),
                "`{sym}` must be lowered in-module (bodied) in {what}"
            );
        }
        // the armed 1723-corruption target exists EXACTLY once per module:
        assert_eq!(
            text.matches("const u64 1723").count(),
            1,
            "the anon-hash seed must appear exactly once in {what} (name_anon)"
        );
    }

    // Helpers over a (text, module) pair.
    let idx_of = |module: &trust_ir::Module, sym: &str| -> usize {
        module
            .functions
            .iter()
            .position(|f| f.name == sym)
            .unwrap_or_else(|| panic!("`{sym}` not in module"))
    };
    let body_of = |text: &'static str, sym: &str| -> &'static str {
        let start = text
            .find(&format!("fn @{sym}("))
            .unwrap_or_else(|| panic!("`{sym}` header present in IR text"));
        let after = &text[start + 1..];
        let end = after
            .find("\nfn @")
            .map(|i| start + 1 + i)
            .unwrap_or(text.len());
        &text[start..end]
    };
    let edge = |text: &'static str, module: &trust_ir::Module, caller: &str, callee: &str| {
        let b = body_of(text, caller);
        let i = idx_of(module, callee);
        assert!(
            b.contains(&format!("@func.{i}(")),
            "`{caller}` must Call @func.{i} = `{callee}` — the composition edge must RUN"
        );
    };
    let no_edge = |text: &'static str, module: &trust_ir::Module, caller: &str, callee: &str| {
        let b = body_of(text, caller);
        let i = idx_of(module, callee);
        assert!(
            !b.contains(&format!("@func.{i}(")),
            "`{caller}` must NOT call `{callee}`"
        );
    };

    // ── the BINDING-AWARE gate module ──
    let module = parse_and_validate(BD_GATE_TRUST_IR, "bnd_gate_root closure");
    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    for sym in [
        "Verifier____env___check_decl_readonly",
        "Verifier____env___infer_sort",
        "Verifier____env___infer_sort_inner",
        "Verifier____env___check_type",
        "Verifier____env___infer_type",
        "Verifier____env___infer_type_core",
        "Verifier____env___open_bvar",
        "Verifier____env___whnf_impl",
        "Verifier____env___whnf_inner",
        "Verifier____env___is_def_eq",
        "Verifier____env___def_eq_inner",
        "Verifier____env___structural_eq",
        "Verifier____env___level_eq",
        "Verifier____env___unfold_const",
        // the R9 surface, re-confirmed:
        "Verifier____env___is_def_eq_proof_irrel",
        "Verifier____env___infer_type_quick_or_full",
        "Verifier____env___type_is_proof_irrelevant",
        "Verifier____env___type_is_quickly_not_in_prop",
        "Verifier____env___try_infer_type_quick",
        "Verifier____env___try_infer_type_quick_inner",
        "Verifier____env___infer_type_infer_only_core",
        // THE R10 SURFACE:
        "Verifier____env___is_def_eq_binding",
        "expr_syntactic_eq",
        "level_vec_syntactic_eq",
        "LocalContext__truncate_to",
        "LocalContext__len",
        "Expr__has_loose_bvars",
        "ExprMeta__has_loose_bvars",
        "Level__is_def_eq",
        "Level__normalize",
        "build_decl_case",
        "build_decl_case_19",
    ] {
        assert!(bodied(sym), "`{sym}` must be lowered in-module (bodied)");
    }
    // The blind chain AND the distinct-FVar control must be ABSENT from the
    // aware gate closure.
    for f in &module.functions {
        assert!(
            !f.name.contains("_blind") && !f.name.contains("distinct_control"),
            "aware gate closure must not contain blind/control fns (found `{}`)",
            f.name
        );
    }
    // THE R10 CALL POSITION: def_eq dispatches binder pairs to binding.
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___def_eq_inner",
        "Verifier____env___is_def_eq_binding",
    );
    // binding's internals — the production :12-64 wiring:
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_binding",
        "LocalContext__len",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_binding",
        "expr_syntactic_eq",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_binding",
        "Expr__has_loose_bvars",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_binding",
        "LocalContext__push",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_binding",
        "name_anon",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_binding",
        "Verifier____env___open_bvar",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_binding",
        "Verifier____env___def_eq_impl",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_binding",
        "LocalContext__truncate_to",
    );
    // the pre-check sees names through name_eq (Let/Const arms):
    edge(BD_GATE_TRUST_IR, &module, "expr_syntactic_eq", "name_eq");
    // the R9 context consults, re-confirmed on the R10 module:
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___whnf_inner",
        "LocalContext__get",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___def_eq_inner",
        "Verifier____env___is_def_eq_proof_irrel",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___try_infer_type_quick_inner",
        "LocalContext__get",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___infer_type_infer_only_core",
        "LocalContext__push",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___infer_type_core",
        "Verifier____env___is_def_eq",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___check_decl_readonly",
        "Verifier____env___infer_sort",
    );
    edge(
        BD_GATE_TRUST_IR,
        &module,
        "Verifier____env___check_decl_readonly",
        "Verifier____env___check_type",
    );

    // ── the BINDING-BLIND control module: the R9-landed configuration ──
    let bmodule = parse_and_validate(BD_BLIND_TRUST_IR, "bnd_blind_root closure");
    let bbodied = |sym: &str| {
        bmodule
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    for sym in [
        "Verifier____env___check_decl_readonly_blind",
        "Verifier____env___is_def_eq_blind",
        "Verifier____env___def_eq_blind_inner",
        "Verifier____env___infer_type_core_blind",
        "Verifier____env___is_def_eq_proof_irrel_blind",
        "Verifier____env___infer_type_quick_or_full_blind",
        "Verifier____env___type_is_proof_irrelevant_blind",
        "Verifier____env___try_infer_type_quick_inner_blind",
        "Verifier____env___infer_type_infer_only_core_blind",
        // the SHARED context-aware whnf (the control is only BINDING-blind):
        "Verifier____env___whnf_impl",
        "Verifier____env___whnf_inner",
    ] {
        assert!(
            bbodied(sym),
            "`{sym}` must be lowered in-module (bodied) in the blind fixture"
        );
    }
    // The AWARE def_eq/binding chain is STRUCTURALLY ABSENT — including the
    // R10 helpers only binding uses (the control has NO opening machinery).
    for f in &bmodule.functions {
        assert!(
            f.name != "Verifier____env___is_def_eq_binding"
                && f.name != "Verifier____env___is_def_eq_binding_distinct_control"
                && f.name != "Verifier____env___def_eq_inner"
                && f.name != "Verifier____env___is_def_eq"
                && f.name != "Verifier____env___infer_type_core"
                && f.name != "Verifier____env___is_def_eq_proof_irrel"
                && f.name != "Verifier____env___infer_type_infer_only_core"
                && f.name != "Verifier____env___check_decl_readonly"
                && f.name != "expr_syntactic_eq"
                && f.name != "LocalContext__truncate_to",
            "blind closure must not contain the aware/binding chain (found `{}`)",
            f.name
        );
    }
    // The blind whnf still consults the context (zeta — R9 kept)…
    edge(
        BD_BLIND_TRUST_IR,
        &bmodule,
        "Verifier____env___whnf_inner",
        "LocalContext__get",
    );
    // …the blind def_eq keeps the proof-irrel consult (R9 kept)…
    edge(
        BD_BLIND_TRUST_IR,
        &bmodule,
        "Verifier____env___def_eq_blind_inner",
        "Verifier____env___is_def_eq_proof_irrel_blind",
    );
    // …and blind INFERENCE is the shared R8/R9 discipline.
    edge(
        BD_BLIND_TRUST_IR,
        &bmodule,
        "Verifier____env___infer_type_core_blind",
        "LocalContext__get",
    );
    edge(
        BD_BLIND_TRUST_IR,
        &bmodule,
        "Verifier____env___infer_type_core_blind",
        "LocalContext__push",
    );

    // ── the probe module carries BOTH chains + the distinct-FVar control ──
    let pmodule = parse_and_validate(BD_PROBE_TRUST_IR, "bnd_probe_root closure");
    let pbodied = |sym: &str| {
        pmodule
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    for sym in [
        "Verifier____env___is_def_eq_binding",
        "Verifier____env___is_def_eq_binding_distinct_control",
        "Verifier____env___def_eq_inner",
        "Verifier____env___is_def_eq_blind",
        "Verifier____env___def_eq_blind_inner",
        "Verifier____env___whnf_inner",
        "expr_syntactic_eq",
        "bnd_probe_root",
    ] {
        assert!(
            pbodied(sym),
            "`{sym}` must be lowered in-module (bodied) in the probe fixture"
        );
    }
    edge(
        BD_PROBE_TRUST_IR,
        &pmodule,
        "bnd_probe_root",
        "Verifier____env___is_def_eq_binding",
    );
    edge(
        BD_PROBE_TRUST_IR,
        &pmodule,
        "bnd_probe_root",
        "Verifier____env___is_def_eq_binding_distinct_control",
    );
    edge(
        BD_PROBE_TRUST_IR,
        &pmodule,
        "bnd_probe_root",
        "Verifier____env___is_def_eq",
    );
    edge(
        BD_PROBE_TRUST_IR,
        &pmodule,
        "bnd_probe_root",
        "Verifier____env___is_def_eq_blind",
    );
    edge(
        BD_PROBE_TRUST_IR,
        &pmodule,
        "bnd_probe_root",
        "expr_syntactic_eq",
    );
    edge(
        BD_PROBE_TRUST_IR,
        &pmodule,
        "bnd_probe_root",
        "LocalContext__push_let",
    );
    edge(
        BD_PROBE_TRUST_IR,
        &pmodule,
        "bnd_probe_root",
        "LocalContext__push",
    );
    edge(
        BD_PROBE_TRUST_IR,
        &pmodule,
        "Verifier____env___is_def_eq_binding",
        "LocalContext__truncate_to",
    );
    edge(
        BD_PROBE_TRUST_IR,
        &pmodule,
        "Verifier____env___is_def_eq_binding_distinct_control",
        "LocalContext__truncate_to",
    );
    // the aware def_eq dispatches to binding in the probe module too:
    edge(
        BD_PROBE_TRUST_IR,
        &pmodule,
        "Verifier____env___def_eq_inner",
        "Verifier____env___is_def_eq_binding",
    );
    // the R9-config def_eq does NOT:
    no_edge(
        BD_PROBE_TRUST_IR,
        &pmodule,
        "Verifier____env___def_eq_blind_inner",
        "Verifier____env___is_def_eq_binding",
    );
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 2 — THE BINDING PROBES, native == JIT at full payload depth: opening
// + irrel-under-binder with the truncate/counter observables; the
// shared-vs-distinct-FVar control; the alpha meta-word pins; the poisoned-
// context flip through binding; reject-path cleanup; the #3230 pre-check /
// fast-path no-push observables; the in-module pair-level aware-vs-R9-config
// divergence.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn bd_probe_binding_differential() {
    let buffer = run_with_watchdog("JIT compile bnd_probe_root", move || {
        jit_module(BD_PROBE_TRUST_IR, "bnd_probe_root closure", &bd_externs())
    });
    let probe: BdProbeFn = unsafe { std::mem::transmute(bind(&buffer, "bnd_probe_root")) };

    let labels: [&str; 7] = [
        "BINDING opens with ONE shared FVar; irrel-under-binder; len restored; next_id +1; R9-config rejects",
        "SHARED-vs-DISTINCT-FVar: binding accepts dependent pair; distinct control rejects; erased pair agrees",
        "ALPHA: bi-differing Lam / name-differing Let — meta bit-identical, pre-check FALSE, def_eq TRUE",
        "POISONED-CONTEXT through binding: wrong let value flips the verdict",
        "REJECT-path cleanup: early truncate restores len; exactly the h-push + one fallback push",
        "#3230 pre-check + no-loose fast path: verdict with ZERO pushes",
        "PAIR DIVERGENCE: aware TRUE, R9-config FALSE on the bzeta pair; R9-config TRUE on the R9 zeta pair",
    ];

    let mut jit_out: Vec<(Result<rn::Expr, rn::TypeError>, rn::ProbeIds)> = Vec::new();
    for idx in 0u64..7 {
        let (nres, nids) = native_probe(idx);
        let (jres, jids) = jit_probe(probe, idx);
        assert_eq!(
            (nids.id0, nids.id1, nids.guard_trips, nids.flags),
            (jids.id0, jids.id1, jids.guard_trips, jids.flags),
            "probe {idx} `{}`: ProbeIds disagree native vs JIT",
            labels[idx as usize]
        );
        let agree = match (&nres, &jres) {
            (Ok(a), Ok(b)) => deep_eq_nj(a, b),
            (Err(a), Err(b)) => type_error_agrees_nj(a, b),
            _ => false,
        };
        assert!(
            agree,
            "probe {idx} `{}`: result disagrees native vs JIT:\n  native = {nres:?}\n  jit    = {jres:?}",
            labels[idx as usize]
        );
        jit_out.push((jres, jids));
    }

    // ── HARD PINS (asserted on the JIT outputs) ──
    // p0: binding TRUE (bit0), ctx len restored (bit1), next_id advanced by
    // EXACTLY 1 (bit2 — ids (3,7): the +1 telescope push happens at id 3;
    // id1 additionally counts the R9-config control's fallback pushes), and
    // the R9-config def_eq REJECTS the same pair (bit3).
    let (res0, ids0) = &jit_out[0];
    assert_eq!(
        (ids0.id0, ids0.id1, ids0.guard_trips, ids0.flags),
        (3, 7, 0, 15),
        "p0: binding-open observables (verdict/len-restore/next_id+1/R9-config-reject)"
    );
    match res0 {
        Ok(e) => match &e.kind {
            rn::ExprKind::Pi(_, dom, body) => {
                assert!(
                    matches!(&dom.kind, rn::ExprKind::FVar(rn::FVarId(0))),
                    "p0 pair lhs domain must be P^ = FVar(0)"
                );
                match &body.kind {
                    rn::ExprKind::Pi(_, dom2, _) => match &dom2.kind {
                        rn::ExprKind::App(f, a) => {
                            assert!(matches!(&f.kind, rn::ExprKind::FVar(rn::FVarId(1))));
                            assert!(matches!(&a.kind, rn::ExprKind::BVar(0)));
                        }
                        other => panic!("p0 inner domain must be App(C^, #0), got {other:?}"),
                    },
                    other => panic!("p0 body must be Pi, got {other:?}"),
                }
            }
            other => panic!("p0 res must be the lhs Pi pair member, got {other:?}"),
        },
        other => panic!("p0 must be Ok(Pi), got {other:?}"),
    }
    // p1: THE SHARED-FVAR DISCIPLINE — production binding TRUE on the
    // dependent pair, the distinct-id control FALSE on it, TRUE on the
    // erased pair.
    let (_, ids1) = &jit_out[1];
    assert_eq!(
        (ids1.id0, ids1.id1, ids1.flags),
        (0, 6, 7),
        "DISTINCT-FVAR CONTROL FAILED: opening with two fresh ids must break dependent equality"
    );
    // p2: ALPHA — all seven observables.
    let (_, ids2) = &jit_out[2];
    assert_eq!(
        ids2.flags, 127,
        "ALPHA FAILED: meta words must be bit-identical, the syntactic pre-check must SEE bi/names, def_eq must not"
    );
    assert_eq!(
        ids2.id0, 1,
        "p2: exactly ONE binding push across both alpha pairs"
    );
    // p3: POISONED-CONTEXT through binding — good TRUE, poisoned FALSE; the
    // poisoned zeta output is Q^' = FVar(1) of the poisoned context.
    let (res3, ids3) = &jit_out[3];
    assert_eq!(
        (ids3.id0, ids3.id1, ids3.flags),
        (3, 4, 3),
        "POISONED-CONTEXT CONTROL FAILED: the wrong let value must flip the binding verdict"
    );
    match res3 {
        Ok(e) => assert!(
            matches!(&e.kind, rn::ExprKind::FVar(rn::FVarId(1))),
            "p3 poisoned zeta must yield Q^' = FVar(1), got {e:?}"
        ),
        other => panic!("p3 must be Ok(FVar 1), got {other:?}"),
    }
    // p4: reject-path cleanup — FALSE, len restored, next_id +2 exactly.
    let (_, ids4) = &jit_out[4];
    assert_eq!(
        (ids4.id0, ids4.id1, ids4.flags),
        (3, 5, 7),
        "REJECT-PATH CLEANUP FAILED: early truncate must restore len; pushes must be h + one fallback"
    );
    // p5: pre-check + fast path — TRUE/FALSE verdicts with ZERO pushes.
    let (_, ids5) = &jit_out[5];
    assert_eq!(
        (ids5.id0, ids5.id1, ids5.flags),
        (0, 0, 7),
        "FAST-PATH FAILED: closed bodies must be compared WITHOUT opening (no push)"
    );
    // p6: pair-level divergence + the control's context-awareness.
    let (_, ids6) = &jit_out[6];
    assert_eq!(
        (ids6.id0, ids6.id1, ids6.flags),
        (3, 8, 7),
        "PAIR-DIVERGENCE FAILED: aware TRUE / R9-config FALSE on bzeta; R9-config TRUE on the R9 zeta pair"
    );

    // Comparator negative control: a meta-corrupted copy must be REJECTED.
    if let Ok(e) = &jit_out[0].0 {
        let corrupted = rn::Expr {
            kind: e.kind.clone(),
            meta: rn::ExprMeta(e.meta.raw() ^ 1),
        };
        assert!(
            !deep_eq_nj(&corrupted, e),
            "NEGATIVE CONTROL FAILED: deep_eq_nj accepted a meta-corrupted expr"
        );
    }

    drop(buffer);
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 3 — the FULL decl-gate differential THROUGH THE BINDING-AWARE DEF_EQ:
// the R9 20-case set re-run (same verdicts, payload-deep — REAL-Name payloads
// raw-decoded + chain-revalidated, expr payloads meta-bit-identical) + the
// three R10 cases = 13 accepts / 10 rejects, native == JIT on every verdict
// and every payload. R6/R8/R9 pinned witnesses re-asserted; fail-loud
// negative controls.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn bd_decl_gate_full_differential() {
    let buffer = run_with_watchdog("JIT compile bnd_gate_root", move || {
        jit_module(BD_GATE_TRUST_IR, "bnd_gate_root closure", &bd_externs())
    });
    let gate: BdGateFn = unsafe { std::mem::transmute(bind(&buffer, "bnd_gate_root")) };

    let labels: [&str; 23] = [
        "ACCEPT ax.polymax{u,v} : Sort(max u v)",
        "REJECT §6 thm.polymax{u,v}",
        "REJECT §4 ax.nested{u}",
        "REJECT §2 ax.dup{u,v,u}",
        "ACCEPT thm.prop [imax(_,0)=0 towers]",
        "REJECT §6 thm.poly{u} [IMax]",
        "ACCEPT def.commute{u,v}",
        "ACCEPT def.dedup{u,v}",
        "REJECT §7 def.wrong{u,v} [TypeMismatch payloads]",
        "REJECT §5 ax.notatype [Const(Nat) payload]",
        "REJECT §3 ax.fvar",
        "ACCEPT opq.poly{u}",
        "ACCEPT ax.constty [env unfold]",
        "REJECT §4 def.valundef{v}",
        "REJECT §4 ax.constlvls{u} [Const LEVELS]",
        "REJECT §2 thm.42{u,u} [Num-part name]",
        "ACCEPT def.zeta [R8 let/zeta]",
        "ACCEPT def.shadow [R8 shadowing]",
        "ACCEPT def.zeta2 [R9: ctx-ZETA inside §7's def_eq]",
        "ACCEPT def.irrel [R9: PROOF IRRELEVANCE decides §7]",
        "ACCEPT def.birrel [R10: irrel over the OPENED domain]",
        "ACCEPT def.bzeta [R10: outer let zeta + inner opening]",
        "ACCEPT def.alpha [R10: binder attrs irrelevant]",
    ];

    let mut accepts = 0usize;
    let mut rejects = 0usize;
    let mut jit_results: Vec<Result<(), rn::EnvError>> = Vec::new();
    for case in 0u64..23 {
        let label = labels[case as usize];
        let (native, nty) = native_gate_aware(case);
        let (jit, jty) = jit_gate(gate, case);
        assert!(
            deep_eq_nj(&nty, &jty),
            "case {case} `{label}`: JIT-built declared type must be meta-bit-identical to native"
        );
        match (&native, &jit) {
            (Ok(()), Ok(())) => accepts += 1,
            (Err(ne), Err(je)) => {
                assert!(
                    env_error_agrees_nj(ne, je),
                    "decl gate JIT disagrees with native on `{label}` (both Err, payloads differ):\n  native = {ne:?}\n  jit    = {je:?}"
                );
                rejects += 1;
            }
            _ => panic!(
                "decl gate JIT vs native ACCEPT/REJECT disagreement on `{label}`:\n  native = {native:?}\n  jit    = {jit:?}"
            ),
        }
        jit_results.push(jit);
    }
    assert_eq!(
        accepts, 13,
        "expected exactly 13 ACCEPTs (0,4,6,7,11,12,16,17,18,19,20,21,22)"
    );
    assert_eq!(rejects, 10, "expected exactly 10 REJECTs");
    // The R9 verdict pattern is REPRODUCED on cases 0..19 through the
    // binding-aware def_eq (the re-run requirement):
    let r9_accepts = [0usize, 4, 6, 7, 11, 12, 16, 17, 18, 19];
    for case in 0..20usize {
        assert_eq!(
            jit_results[case].is_ok(),
            r9_accepts.contains(&case),
            "case {case}: verdict must match the landed R9 gate"
        );
    }
    // The three R10 binding cases ACCEPT (opening-into-the-context live):
    assert!(
        jit_results[20].is_ok(),
        "case 20 (irrel over the opened domain) must ACCEPT"
    );
    assert!(
        jit_results[21].is_ok(),
        "case 21 (outer let zeta + inner opening) must ACCEPT"
    );
    assert!(jit_results[22].is_ok(), "case 22 (alpha) must ACCEPT");

    // ── R6/R8/R9 pinned witnesses, re-asserted through the binding pillars. ──
    let expected_imax = rn::Level::IMax(
        Arc::new(rn::Level::Succ(Arc::new(rn::Level::Param(hn1("u"))))),
        Arc::new(rn::Level::Param(hn1("u"))),
    );
    let jit5_sort = match &jit_results[5] {
        Err(rn::EnvError::TheoremTypeNotProp { sort, .. }) => sort.clone(),
        other => panic!("case 5 must be TheoremTypeNotProp, got {other:?}"),
    };
    assert!(
        level_eq_nj(&expected_imax, &jit5_sort),
        "case 5: JIT-built sort payload must be IMax(succ u, u); got {jit5_sort:?}"
    );
    let (j8_exp, _j8_inf) = match &jit_results[8] {
        Err(rn::EnvError::TypeCheckFailed {
            source: rn::TypeError::TypeMismatch { expected, inferred },
            ..
        }) => (expected.clone(), inferred.clone()),
        other => panic!("case 8 JIT must be TypeMismatch, got {other:?}"),
    };
    match &jit_results[9] {
        Err(rn::EnvError::TypeCheckFailed {
            source: rn::TypeError::ExpectedSort { ty },
            ..
        }) => match &ty.kind {
            rn::ExprKind::Const(n, levels) => {
                assert!(levels.is_empty(), "case 9: Const(Nat) must carry no levels");
                let (comps, h, _) = unsafe { decode_jit_name(n as *const rn::Name as *const u8) };
                assert_eq!(
                    h, GOLDEN_NAT,
                    "case 9: the Lit-rule type name must be the kernel `Nat` golden"
                );
                assert_eq!(comps, vec![Comp::Str(b"Nat".to_vec())]);
            }
            other => panic!("case 9 payload must be Const(Nat), got {other:?}"),
        },
        other => panic!("case 9 must be ExpectedSort, got {other:?}"),
    }
    match &jit_results[3] {
        Err(rn::EnvError::DuplicateLevelParam { name, param }) => {
            let (_, nh, _) = unsafe { decode_jit_name(name as *const rn::Name as *const u8) };
            assert_eq!(
                nh, GOLDEN_AX_DUP,
                "case 3: decl-name hash must be the `ax.dup` golden"
            );
            let (_, ph, _) = unsafe { decode_jit_name(param as *const rn::Name as *const u8) };
            assert_eq!(
                ph, GOLDEN_U,
                "case 3: the duplicate param must decode to the `u` golden"
            );
        }
        other => panic!("case 3 must be DuplicateLevelParam, got {other:?}"),
    }
    match &jit_results[15] {
        Err(rn::EnvError::DuplicateLevelParam { name, .. }) => {
            let (ncomps, nh, _) = unsafe { decode_jit_name(name as *const rn::Name as *const u8) };
            assert_eq!(
                nh, GOLDEN_THM42,
                "case 15: decl-name hash must be the `thm.42` golden"
            );
            assert_eq!(ncomps, vec![Comp::Num(42), Comp::Str(b"thm".to_vec())]);
        }
        other => panic!("case 15 must be DuplicateLevelParam, got {other:?}"),
    }
    match &jit_results[14] {
        Err(rn::EnvError::UndefinedLevelParam { param, .. }) => {
            let (_, ph, _) = unsafe { decode_jit_name(param as *const rn::Name as *const u8) };
            assert_eq!(
                ph, GOLDEN_V,
                "case 14: the undef param inside Const levels must be `v`"
            );
        }
        other => panic!("case 14 must be UndefinedLevelParam, got {other:?}"),
    }
    // R10 declared-type shape pins (JIT-built):
    let (_, jty20) = jit_gate(gate, 20);
    match &jty20.kind {
        rn::ExprKind::Pi(_, dom, body) => {
            assert!(matches!(&dom.kind, rn::ExprKind::Sort(rn::Level::Zero)));
            assert!(
                matches!(&body.kind, rn::ExprKind::Pi(..)),
                "case 20 declared type must be the Pi telescope"
            );
        }
        other => panic!("case 20 declared type must be Pi, got {other:?}"),
    }
    let (_, jty22) = jit_gate(gate, 22);
    match &jty22.kind {
        // THE ALPHA PIN: the JIT-built declared type carries the DIFFERING
        // binder data (info 1 outer / info 3 inner) that the accepted
        // equality ignored — and the redex body.
        rn::ExprKind::Pi(b_outer, dom, body) => {
            assert_eq!(
                (b_outer.info, b_outer.mult),
                (1, 2),
                "case 22: outer bi must be info=1"
            );
            assert!(matches!(&dom.kind, rn::ExprKind::Sort(rn::Level::Zero)));
            match &body.kind {
                rn::ExprKind::Pi(b_inner, dom2, body2) => {
                    assert_eq!(
                        (b_inner.info, b_inner.mult),
                        (3, 2),
                        "case 22: inner bi must be info=3"
                    );
                    assert!(matches!(&dom2.kind, rn::ExprKind::BVar(0)));
                    assert!(
                        matches!(&body2.kind, rn::ExprKind::App(..)),
                        "case 22: the declared body must be the beta redex"
                    );
                }
                other => panic!("case 22 inner must be Pi, got {other:?}"),
            }
        }
        other => panic!("case 22 declared type must be Pi, got {other:?}"),
    }

    // ── NC1 (fail-loud): an always-accept gate must DISAGREE with native on
    //    the wrong-universe definition. ──
    let (native8, _) = native_gate_aware(8);
    assert!(
        native8.is_err(),
        "control: native gate MUST reject the wrong-universe definition"
    );
    let always_accept = |_c: u64| -> Result<(), rn::EnvError> { Ok(()) };
    let bogus = always_accept(8);
    assert_ne!(
        native8.is_ok(),
        bogus.is_ok(),
        "NEGATIVE CONTROL FAILED: an always-accept gate agreed with native"
    );
    // ── NC2 (fail-loud): wrong universe expectations must be REJECTED. ──
    assert!(
        !level_eq_nj(&rn::Level::Zero, &jit5_sort),
        "NEGATIVE CONTROL FAILED: comparator equated IMax(succ u, u) with Zero"
    );
    let crossed_imax = rn::Level::IMax(
        Arc::new(rn::Level::Succ(Arc::new(rn::Level::Param(hn1("v"))))),
        Arc::new(rn::Level::Param(hn1("v"))),
    );
    assert!(
        !level_eq_nj(&crossed_imax, &jit5_sort),
        "NEGATIVE CONTROL FAILED: comparator equated IMax(succ u, u) with IMax(succ v, v)"
    );
    // ── NC3 (fail-loud): a meta-word-corrupted copy must be REJECTED. ──
    let corrupted = rn::Expr {
        kind: j8_exp.kind.clone(),
        meta: rn::ExprMeta(j8_exp.meta.raw() ^ 1),
    };
    assert!(
        !deep_eq_nj(&corrupted, &j8_exp),
        "NEGATIVE CONTROL FAILED: deep_eq_nj accepted a meta-corrupted expr"
    );

    drop(buffer);
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 4 — THE BINDING-BLIND DIVERGENCE (the falsifiability proof): the
// R9-landed-configuration control gate runs the SAME 23 cases native==JIT,
// agrees with the binding-aware gate on cases 0-19 AND 22 (it ACCEPTS the R9
// pair 18/19 — context-aware, only binding-blind), and REJECTS exactly
// {20, 21} — with the rejection payloads pinned to the un-openable shapes:
// the SAME stuck head C^ applied to the loose BVar #0 (inferred side) vs the
// proof FVar hp^ (expected side), under equal outer domains (P^ in 20; the
// let-FVar T^ in 21).
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn bd_blind_divergence_differential() {
    let buffer = run_with_watchdog("JIT compile bnd_blind_root", move || {
        jit_module(BD_BLIND_TRUST_IR, "bnd_blind_root closure", &bd_externs())
    });
    let gate: BdGateFn = unsafe { std::mem::transmute(bind(&buffer, "bnd_blind_root")) };

    let mut baccepts = 0usize;
    let mut jit_blind: Vec<Result<(), rn::EnvError>> = Vec::new();
    for case in 0u64..23 {
        // The blind control is itself verified native==JIT (verdict + payload).
        let (native, nty) = native_gate_blind(case);
        let (jit, jty) = jit_gate(gate, case);
        assert!(
            deep_eq_nj(&nty, &jty),
            "blind case {case}: JIT-built declared type must be meta-bit-identical to native"
        );
        match (&native, &jit) {
            (Ok(()), Ok(())) => baccepts += 1,
            (Err(ne), Err(je)) => assert!(
                env_error_agrees_nj(ne, je),
                "blind gate JIT disagrees with native on case {case}:\n  native = {ne:?}\n  jit    = {je:?}"
            ),
            _ => panic!(
                "blind gate JIT vs native verdict disagreement on case {case}:\n  native = {native:?}\n  jit    = {jit:?}"
            ),
        }
        jit_blind.push(jit);
    }
    assert_eq!(
        baccepts, 11,
        "the blind gate must accept exactly the 10 R9 accepts + case 22"
    );

    // THE DIVERGENCE CONTRACT: blind verdict != aware verdict EXACTLY on
    // {20, 21}; identical everywhere else (both compared as native oracles
    // AND as JIT results). In particular the R9 divergence pair 18/19 now
    // AGREES — the control kept R9's context consults.
    for case in 0u64..23 {
        let (aware, _) = native_gate_aware(case);
        let expect_diverge = case == 20 || case == 21;
        let diverged = aware.is_ok() != jit_blind[case as usize].is_ok();
        assert_eq!(
            diverged,
            expect_diverge,
            "case {case}: blind-vs-aware divergence contract violated (aware={:?}, blind={:?})",
            aware.is_ok(),
            jit_blind[case as usize].is_ok()
        );
    }
    assert!(
        jit_blind[18].is_ok(),
        "blind must ACCEPT case 18 (R9 ctx-zeta — the control is context-aware)"
    );
    assert!(
        jit_blind[19].is_ok(),
        "blind must ACCEPT case 19 (R9 proof irrel — the control is context-aware)"
    );
    assert!(
        jit_blind[22].is_ok(),
        "blind must ACCEPT case 22 (raw congruence also ignores binder attrs)"
    );

    // Pinned REJECT shapes — the failures are precisely the un-openable
    // comparisons (not incidental errors). Shared pin helper: a
    // TypeMismatch whose two sides are Pi telescopes with EQUAL outer
    // domain FVars, the SAME inner stuck head C^, and DIVERGING inner args
    // (expected: the proof FVar hp^; inferred: the loose BVar #0 that only
    // OPENING could have typed).
    let pin_unopenable = |res: &Result<(), rn::EnvError>, case: &str| {
        let (expected, inferred) = match res {
            Err(rn::EnvError::TypeCheckFailed {
                source: rn::TypeError::TypeMismatch { expected, inferred },
                ..
            }) => (expected.clone(), inferred.clone()),
            other => panic!("blind {case} must be TypeCheckFailed(TypeMismatch), got {other:?}"),
        };
        let (e_dom, e_body) = match &expected.kind {
            rn::ExprKind::Pi(_, d, b) => (d.clone(), b.clone()),
            other => panic!("blind {case} expected must be Pi, got {other:?}"),
        };
        let (i_dom, i_body) = match &inferred.kind {
            rn::ExprKind::Pi(_, d, b) => (d.clone(), b.clone()),
            other => panic!("blind {case} inferred must be Pi, got {other:?}"),
        };
        let e_outer = match &e_dom.kind {
            rn::ExprKind::FVar(i) => *i,
            other => panic!("blind {case} expected outer domain must be an FVar, got {other:?}"),
        };
        let i_outer = match &i_dom.kind {
            rn::ExprKind::FVar(i) => *i,
            other => panic!("blind {case} inferred outer domain must be an FVar, got {other:?}"),
        };
        assert_eq!(
            e_outer, i_outer,
            "blind {case}: both outer domains share one FVar"
        );
        let e_inner = match &e_body.kind {
            rn::ExprKind::Pi(_, d, _) => d.clone(),
            other => panic!("blind {case} expected body must be Pi, got {other:?}"),
        };
        let i_inner = match &i_body.kind {
            rn::ExprKind::Pi(_, d, _) => d.clone(),
            other => panic!("blind {case} inferred body must be Pi, got {other:?}"),
        };
        let (ef, ea) = match &e_inner.kind {
            rn::ExprKind::App(f, a) => (f.clone(), a.clone()),
            other => panic!("blind {case} expected inner domain must be App, got {other:?}"),
        };
        let (inf, ina) = match &i_inner.kind {
            rn::ExprKind::App(f, a) => (f.clone(), a.clone()),
            other => panic!("blind {case} inferred inner domain must be App, got {other:?}"),
        };
        let head_e = match &ef.kind {
            rn::ExprKind::FVar(i) => *i,
            other => panic!("blind {case} expected head must be FVar, got {other:?}"),
        };
        let head_i = match &inf.kind {
            rn::ExprKind::FVar(i) => *i,
            other => panic!("blind {case} inferred head must be FVar, got {other:?}"),
        };
        assert_eq!(
            head_e, head_i,
            "blind {case}: both sides share the stuck head C^"
        );
        assert!(
            matches!(&ea.kind, rn::ExprKind::FVar(_)),
            "blind {case}: the expected inner arg must be the proof FVar hp^"
        );
        assert!(
            matches!(&ina.kind, rn::ExprKind::BVar(0)),
            "blind {case}: the inferred inner arg must be the LOOSE BVar #0 (only OPENING could type it)"
        );
        e_outer
    };
    // case 20: the outer domain is P^ (a plain decl).
    pin_unopenable(&jit_blind[20], "case 20 (birrel)");
    // case 21: the outer domain is the LET-FVar T^ — pushed by §7's Let arm
    // OUTSIDE the comparison; its id is strictly above the P/C/hp opens.
    let t_id = pin_unopenable(&jit_blind[21], "case 21 (bzeta)");
    assert!(
        t_id.0 >= 3,
        "blind case 21: the outer domain must be the LET-FVar (pushed after P^,C^,hp^)"
    );

    drop(buffer);
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 5 — ARMED MODULE-TEXT CORRUPTION: flip the anon-hash seed constant in
// the BINDING-AWARE GATE module's MACHINE-CODE source (`const u64 1723` ->
// 1724, the one occurrence inside name_anon), re-JIT, and assert the case-3
// payload Names diverge EXACTLY as the production chain predicts while the
// gate verdict CLASS is untouched — the hash chain runs IN the JIT machine
// code and the golden pins are not vacuous.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn bd_armed_module_corruption_diverges() {
    assert_eq!(BD_GATE_TRUST_IR.matches("const u64 1723").count(), 1);
    let corrupted_text = BD_GATE_TRUST_IR.replace("const u64 1723", "const u64 1724");
    assert_ne!(corrupted_text, BD_GATE_TRUST_IR);

    let buffer = run_with_watchdog("JIT compile CORRUPTED bnd_gate_root", move || {
        jit_module(
            &corrupted_text,
            "CORRUPTED bnd_gate_root closure",
            &bd_externs(),
        )
    });
    let gate: BdGateFn = unsafe { std::mem::transmute(bind(&buffer, "bnd_gate_root")) };

    // Case 3 (§2 duplicate param): the DISCIPLINE is untouched by the hash
    // corruption — still DuplicateLevelParam…
    let (res3, _ty3) = jit_gate(gate, 3);
    let (name, param) = match &res3 {
        Err(rn::EnvError::DuplicateLevelParam { name, param }) => (name, param),
        other => panic!("corrupted case 3 must still be DuplicateLevelParam, got {other:?}"),
    };
    // …but every constructed Name hash DIVERGES, exactly as predicted.
    // RAW decode (no chain revalidation — the chain is INTENTIONALLY broken).
    let read_u64 = |p: *const u8| -> u64 { unsafe { (p as *const u64).read_unaligned() } };
    let ph = read_u64(unsafe { (param as *const rn::Name as *const u8).add(32) });
    assert_ne!(
        ph, GOLDEN_U,
        "ARMED CONTROL FAILED: the corrupted module still produced the kernel `u` golden — the 1723 seed is not live in machine code"
    );
    let predicted_u = native_mix_hash(1724, native_murmur_hash_64a(b"u", 11));
    assert_eq!(
        ph, predicted_u,
        "the corrupted `u` hash must diverge EXACTLY as the production chain predicts (seed 1724)"
    );
    let nh = read_u64(unsafe { (name as *const rn::Name as *const u8).add(32) });
    let predicted_axdup = native_mix_hash(
        native_mix_hash(1724, native_murmur_hash_64a(b"ax", 11)),
        native_murmur_hash_64a(b"dup", 11),
    );
    assert_ne!(nh, GOLDEN_AX_DUP);
    assert_eq!(
        nh, predicted_axdup,
        "the corrupted `ax.dup` hash must follow the full production chain from seed 1724"
    );
    // and the UNCORRUPTED predictions are the goldens — the oracle is sharp.
    assert_eq!(
        native_mix_hash(GOLDEN_ANON, native_murmur_hash_64a(b"u", 11)),
        GOLDEN_U
    );
    assert_eq!(
        native_mix_hash(
            native_mix_hash(GOLDEN_ANON, native_murmur_hash_64a(b"ax", 11)),
            native_murmur_hash_64a(b"dup", 11)
        ),
        GOLDEN_AX_DUP
    );

    drop(buffer);
}
